/**
 * Paging, and the rule that `select` is mandatory.
 *
 * `retrieveMultipleRecordsAsync` returns one page plus a `skipToken`. The canvas app had no
 * equivalent: `ClearCollect` simply stopped at
 * `DefaultConnectedDataSourceMaxGetRowsCount: 2000` and gave no indication it had truncated.
 * `fetchAll` follows the token, so a project with more cost rows than the old cap does not
 * quietly lose them.
 */
import type { IOperationOptions, IOperationResult } from "@microsoft/power-apps/data";
import { getClient } from "@microsoft/power-apps/data";
// Generated by `pac code add-data-source`; the same import the generated services use.
import { dataSourcesInfo } from "../../.power/schemas/appschemas/dataSourcesInfo";
import { DataError, RecordGoneError, asRecordGone, unwrap } from "@/platform/errors";
import { trace } from "@/platform/telemetry";
import { guid } from "./odata";

export { RecordGoneError };

/** One page of a table. */
type PageFn<T> = (options: IOperationOptions) => Promise<IOperationResult<T[]>>;

export interface FetchAllOptions extends Omit<IOperationOptions, "filter"> {
  /**
   * `$select` is required, not optional. Dataverse returns EVERY column without it â€” on
   * `vsb_projects` that is 112 columns per row â€” and the formatted-value annotations on top.
   */
  select: string[];
  /**
   * Optional, and `undefined` means NO `$filter` at all.
   *
   * The builders in `./odata` return `undefined` rather than `""` for exactly this reason:
   * an empty `$filter=` is a 400, so the key is stripped below instead of forwarded blank.
   */
  filter?: string | undefined;
  /** Safety valve. Exceeding it is a bug in the caller's filter, so it traces loudly. */
  maxPages?: number;
}

/** Drops keys whose value is undefined, so `{filter: undefined}` never becomes `$filter=`. */
function compact(options: Record<string, unknown>): IOperationOptions {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(options)) if (v !== undefined) out[k] = v;
  return out as IOperationOptions;
}

const DEFAULT_MAX_PAGES = 50;
const DEFAULT_PAGE_SIZE = 500;

export async function fetchAll<T>(
  operation: string,
  page: PageFn<T>,
  options: FetchAllOptions,
): Promise<T[]> {
  const { maxPages = DEFAULT_MAX_PAGES, ...query } = options;
  const rows: T[] = [];
  let skipToken: string | undefined;
  let pages = 0;

  do {
    const result = await page(compact({
      maxPageSize: DEFAULT_PAGE_SIZE,
      ...query,
      ...(skipToken ? { skipToken } : {}),
    }));
    rows.push(...unwrap(result, `${operation} (page ${pages + 1})`));
    skipToken = result.skipToken;
    pages += 1;
    if (pages >= maxPages && skipToken) {
      // Truncating silently is exactly the canvas behaviour this function exists to avoid,
      // so say so rather than returning a plausible-looking short list.
      trace(
        "error",
        `${operation} stopped after ${pages} pages with more rows available â€” the filter is too broad`,
        { rows: rows.length },
      );
      break;
    }
  } while (skipToken);

  return rows;
}

/** A single page, for the cases where one page is genuinely all that is wanted. */
export async function fetchPage<T>(
  operation: string,
  page: PageFn<T>,
  options: FetchAllOptions,
): Promise<T[]> {
  const { maxPages: _ignored, ...query } = options;
  return unwrap(
    await page(compact({ maxPageSize: DEFAULT_PAGE_SIZE, ...query })),
    operation,
  );
}

/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• writes â•â• */

/**
 * A delete whose failure is observable.
 *
 * The generated services declare `delete(id): Promise<void>` and **discard** the
 * `IOperationResult` the SDK hands back, so a Dataverse refusal â€” a 403 from row-level
 * security, a cascade the server would not perform â€” resolves exactly like a success. The SDK
 * never throws for a failed data call (see `platform/errors.ts`), so there is nothing else to
 * catch: the row stays, the screen says it went, and the user finds out later.
 *
 * `vsb_projects` is the one table where the canvas app itself refused to ignore that: the
 * delete is wrapped in `IfError` with an error notification. Reproducing that behaviour needs
 * the result, so this goes to the client directly â€” the same reason `countedPage` below does,
 * and for the same kind of gap in pac output, which must not be hand-edited.
 */
export async function deleteRecord(
  operation: string,
  tableName: string,
  recordId: string,
): Promise<void> {
  const client = getClient(dataSourcesInfo);
  unwrap(await client.deleteRecordAsync(tableName, recordId), operation);
}

/**
 * Runs an SDK call; a THROWN error becomes a `DataError(operation)` (an unregistered table can
 * make the SDK throw before any request is sent) and `success: false` is unwrapped into one.
 * Already-typed errors pass through. Re-exported by `./rawTable`, where it started.
 */
export async function guardedCall<T>(operation: string, call: () => Promise<IOperationResult<T>>): Promise<T> {
  let result: IOperationResult<T>;
  try {
    result = await call();
  } catch (error) {
    throw error instanceof DataError ? error : new DataError(operation, error);
  }
  return unwrap(result, operation);
}

/* ══════════════════════════════════════════════════ guarded single-row update ══ */

/** The slice of the SDK client `updateRecordIfExists` uses (injectable for tests). */
export interface GuardedUpdateClient {
  retrieveMultipleRecordsAsync<T>(table: string, options?: IOperationOptions): Promise<IOperationResult<T[]>>;
  updateRecordAsync<TIn, TOut>(table: string, id: string, record: TIn): Promise<IOperationResult<TOut>>;
}

export interface UpdateIfExistsOptions {
  /**
   * The table's primary-key column. Defaults to `primaryKey` in the generated `dataSourcesInfo`;
   * REQUIRED for a table that is not a registered data source yet (e.g. the checklist tables).
   * With neither, the update is refused (fail closed) rather than sent unguarded.
   */
  primaryKey?: string;
  client?: () => GuardedUpdateClient;
}

/** `primaryKey` of a registered data source, or undefined. */
export function primaryKeyOf(tableName: string): string | undefined {
  const info = (dataSourcesInfo as Record<string, { primaryKey?: string } | undefined>)[tableName];
  return info?.primaryKey || undefined;
}

/**
 * V-1 (shared) — a single-row update that can NEVER recreate a deleted row.
 *
 * HISTORY: with `@microsoft/power-apps` 1.3.1 the SDK sent `updateRecordAsync` as
 * `PATCH <set>(<id>)` with NO `If-Match` header (and the public API still has no headers/options
 * parameter). A Web API PATCH without `If-Match: *` is an UPSERT, so updating a row another user
 * had just deleted silently created a NEW row holding only the patched columns.
 *
 * SDK 1.5.0: `runtimeDataClient.updateDataAsync` now ALWAYS adds `If-Match: *` to a Dataverse
 * PATCH (`dist/internal/data/core/runtimeClient/runtimeDataClient.js:95-101`; `_createHeaders`
 * copies it into the batch part's headers, `:309`, or sends it directly when the request is not
 * batched). The PATCH is therefore update-only: a missing id is refused with 404 instead of being
 * recreated. That CLOSES the race this guard used to leave open (a delete landing between the read
 * and the PATCH): such a PATCH now fails, and a 404 is mapped to `RecordGoneError` here
 * (`asRecordGone`). (`UpdateMultiple` — the `Update` message POSTed via `customapi`, see
 * `./bulkWrite` — always failed on a missing id.)
 *
 * WHY THE EXISTENCE READ IS KEPT: it is no longer what prevents resurrection, but it is still the
 * only way to report "gone" reliably. Whether the host surfaces the PATCH's 404 as
 * `error.status` (`parseHttpPluginError` reads it from the plugin's response) — in particular for a
 * PATCH sent inside the SDK's `$batch` — is not verified live yet; until it is, the read turns the
 * common case (deleted before this save started) into a typed `RecordGoneError` with nothing sent.
 * Without a recognisable 404 the rare race case still writes nothing; it just surfaces as a
 * generic `DataError`. Cost: one small GET per single-row update.
 *
 * WHAT: read the row by id (primary key only, one row); if absent throw `RecordGoneError`
 * (a `DataError` with status 404) and send nothing; otherwise PATCH and `unwrap` the result,
 * mapping a 404 to `RecordGoneError`. Any other failed read or PATCH surfaces as a `DataError`,
 * never as "gone".
 */
export async function updateRecordIfExists<TFields, TResult = unknown>(
  operation: string,
  tableName: string,
  recordId: string,
  fields: TFields,
  options: UpdateIfExistsOptions = {},
): Promise<TResult> {
  const primaryKey = options.primaryKey ?? primaryKeyOf(tableName);
  if (!primaryKey) {
    throw new DataError(operation, `no primary key is known for ${tableName}; refusing an unguarded update`);
  }
  let id: string;
  try {
    id = guid(recordId);
  } catch (error) {
    throw new DataError(operation, error);
  }
  const client = options.client ?? (() => getClient(dataSourcesInfo) as unknown as GuardedUpdateClient);

  const found = await guardedCall(`${operation} (existence check)`, () =>
    client().retrieveMultipleRecordsAsync<Record<string, unknown>>(tableName, {
      select: [primaryKey],
      filter: `${primaryKey} eq ${id}`,
      maxPageSize: 1,
    }),
  );
  if (found.length === 0) throw new RecordGoneError(operation, tableName, id);

  // The normalised id: the same value the existence check just looked up. No partitionId: none of
  // this app's tables is elastic (SDK 1.5 only uses it to address `(pk=…,partitionid=…)`).
  try {
    return await guardedCall(operation, () => client().updateRecordAsync<TFields, TResult>(tableName, id, fields));
  } catch (error) {
    // SDK 1.5 sends `If-Match: *`: a row deleted after the read fails with 404, never upserts.
    throw asRecordGone(error, operation, tableName, id);
  }
}

/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• counted paging â•â• */

/**
 * A page of rows plus the server-side total, paged with a SKIP TOKEN.
 *
 * **Dataverse does not support `$skip`.** It answers
 * `{"code":"0x80060888","message":"Skip Clause is not supported in CRM"}`. Paging is
 * forward-only through `@odata.nextLink`, which the SDK surfaces as `skipToken` on both the
 * request and the result. That is why this walks rather than jumps, and it is also why the
 * canvas pager only ever had First / Previous / Next and no page-number box.
 *
 * A cold walk to page N costs N sequential requests: a shared link that names page 3 walks
 * pages 1 and 2 to get there, which is the honest cost of a forward-only cursor. Once walked,
 * the tokens are replayed for `TOKEN_TTL_MS`, so Next, Previous and a jump to any page already
 * passed cost one request; React Query's cache (see `useProjectPage`) makes a revisit free.
 *
 * Why not the generated service: `IGetAllOptions` in `src/generated/models/CommonModels.ts`
 * declares no `count`, though the SDK's `IOperationOptions` does and the runtime honours it.
 * That file is pac output and must not be hand-edited.
 *
 * `@odata.count` is capped at 5000 by the platform, so a filtered set larger than that
 * reports exactly 5000. At 1,129 projects that is far off, but it is a real ceiling.
 */
export interface CountedPage<T> {
  rows: T[];
  /** `@odata.count` for the whole filtered set. Capped at 5000 by the platform. */
  totalRows: number;
  /** 1-based, and clamped to what actually exists. */
  page: number;
  /** True when the server returned a token for a further page. */
  hasNext: boolean;
}

/**
 * One query's walk: the skip token that opens each page (`tokens[0]` is always undefined â€”
 * page 1) and the total counted when page 1 was read.
 */
interface Walk {
  tokens: (string | undefined)[];
  total: number;
  /** When page 1 was read. Tokens are trusted for `TOKEN_TTL_MS` after that, no longer. */
  at: number;
}

/**
 * How long a walk's tokens are replayed. Page P otherwise costs P sequential round trips, which
 * is what made deep pages and Next-after-Previous slow. A skip token is a paging cookie and
 * Dataverse says a page re-read later "can be different" when rows were added or removed in
 * between, so the replay window is short and sits just above React Query's 30 s `staleTime`: a
 * page is never built from a cookie older than the cached page it would replace.
 */
const TOKEN_TTL_MS = 60_000;

/** Walk caches, keyed by query signature and page size. */
const tokenCache = new Map<string, Walk>();

/** Discards the walk when the filter or sort changes; a stale token returns the wrong rows. */
export function resetPageTokens(signature?: string): void {
  if (signature === undefined) tokenCache.clear();
  else tokenCache.delete(signature);
}

export interface CountedPageRequest extends FetchAllOptions {
  /** Rows per page. */
  top: number;
  /** 1-based. */
  page: number;
  /**
   * Identifies the query the tokens belong to â€” the filter and the sort. Two different
   * filters must never share a token.
   */
  signature: string;
}

export async function countedPage<T>(
  operation: string,
  tableName: string,
  request: CountedPageRequest,
): Promise<CountedPage<T>> {
  const { maxPages: _ignored, maxPageSize: _sdkDefault, top, page, signature, ...query } = request;
  const client = getClient(dataSourcesInfo);
  const wanted = Math.max(1, Math.floor(page) || 1);

  /*
   * SOURCE DEFECT (data layer, not a canvas one): the page size travels as `maxPageSize`, NEVER
   * as `$top`.
   *
   * The SDK sends `Prefer: odata.maxpagesize=<maxPageSize ?? 500>` on every read, and Dataverse
   * documents that with that header present "`$top` is ignored" (Web API > Query data > Page
   * results). So `top: 200` used to mean "pages of 500": the grid showed 500 rows against a
   * pager that counted 200, `totalPages` came from `count / 200` while the skip-token chain
   * ran out after `count / 500` pages, and a Next past the end of that chain quietly re-served
   * the last real page under a higher page number. The same header is also what the skip
   * tokens are bound to ("use the same odata.maxpagesize preference value used in the
   * original request"), so it is part of the cache key below.
   */
  const cacheKey = `${signature}|${top}`;

  const fetchAt = async (tokens: (string | undefined)[], index: number) => {
    const result = await client.retrieveMultipleRecordsAsync<T>(
      tableName,
      /*
       * EVERY request of a walk carries identical query options (`$select`, `$filter`,
       * `$orderby`, `$count`) and the same `maxPageSize`. Dataverse: "Don't change the
       * `@odata.nextLink` URL value or append any query options to it" and "use the same
       * `odata.maxpagesize` preference value used in the original request". A skip token
       * issued for a `$count=true` request is therefore never replayed on a request that asks
       * for something different â€” that is how a deep page, the last one above all, stops
       * rendering. `@odata.count` is capped at 5000, so asking every time stays cheap.
       */
      compact({ ...query, maxPageSize: top, count: true, skipToken: tokens[index] }),
    );
    const rows = unwrap(result, `${operation} (page ${index + 1})`);
    if (result.skipToken) tokens[index + 1] = result.skipToken;
    return { rows, count: result.count, next: result.skipToken };
  };

  const walkTo = async (cached: Walk | undefined) => {
    const tokens = cached?.tokens ?? [undefined];
    // Resume from the furthest page at or before the wanted one whose token is known.
    let index = 0;
    for (let i = Math.min(wanted - 1, tokens.length - 1); i > 0; i -= 1) {
      if (tokens[i]) { index = i; break; }
    }

    // An uncached walk always opens on page 1.
    let current = await fetchAt(tokens, index);
    const first = current;
    // Walk forward to the requested page, stopping early if the data runs out.
    while (index + 1 < wanted && current.next) {
      index += 1;
      current = await fetchAt(tokens, index);
    }

    // The total comes from PAGE 1, never from whichever page was served last: a later page is
    // not guaranteed to repeat `@odata.count`, and `rows.length` of a page 2 is not a total.
    const walk: Walk = cached ?? {
      tokens,
      total: first.count ?? first.rows.length,
      at: Date.now(),
    };
    tokenCache.set(cacheKey, walk);

    return {
      rows: current.rows,
      totalRows: walk.total,
      page: index + 1,
      hasNext: Boolean(current.next),
    };
  };

  /*
   * Replays the walk's cached skip tokens while they are fresh, so a page costs one request
   * instead of one per page before it. The total rides along with them (counted once, on
   * page 1). A replay that fails â€” an expired or invalidated cookie â€” falls back to a clean
   * walk from page 1 rather than surfacing an error the user did not cause.
   */
  const cached = tokenCache.get(cacheKey);
  if (cached && Date.now() - cached.at < TOKEN_TTL_MS) {
    try {
      return await walkTo(cached);
    } catch {
      tokenCache.delete(cacheKey);
    }
  }
  return walkTo(undefined);
}
